import rotasegura.dao.*;import rotasegura.service.*;public class Teste{public static void main(String[] a)throws Exception{try(Repositorio r=new Repositorio("jdbc:hsqldb:mem:teste")){Locadora s=new Locadora(r);s.cliente(false,"12345678901","Teste","123");s.abrir("12345678901","ABC-1234",2);int id=((Number)r.locacoes().get(0)[0]).intValue();if(!Boolean.FALSE.equals(r.veiculo("ABC-1234")[5]))throw new Error();s.fechar(id,3);if(!Boolean.TRUE.equals(r.veiculo("ABC-1234")[5]))throw new Error();System.out.println(s.resumo(id,3));}}}
